{
  "propositions": [
    {
      "id": "P1",
      "proposition": "Replacing § 49-6-2302, the bill requires each local board of education to establish school lunch and breakfast programs providing free lunch and breakfast to every student enrolled in a school under its jurisdiction who is eligible for free or reduced-price meals, according to rules established under § 49-6-2303.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "Each local board of education shall establish a school lunch program and a\n\n school breakfast program that provides a free lunch and breakfast to each student"
    },
    {
      "id": "P2",
      "proposition": "Subject to available funding, the state must reimburse each LEA for the cost of free breakfast and lunch served to its enrolled students eligible for reduced-price meals after all available federal funds under the national school lunch program, school breakfast program, or any other federal program have been applied.",
      "importance": "core",
      "section": "SECTION 1",
      "source_quote": "Subject to available funding, the state shall reimburse each LEA the cost of\n\n providing a free breakfast and lunch served to each student enrolled in the LEA who is\n\n eligible for reduced price meals"
    },
    {
      "id": "P3",
      "proposition": "The bill deletes the language \", regardless of its participation\" from § 49-6-2303(5).",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "the language \", regardless of its participation\" in subdivision (5)"
    },
    {
      "id": "P4",
      "proposition": "The bill deletes § 49-6-2303(10).",
      "importance": "supporting",
      "section": "SECTION 2",
      "source_quote": "by deleting subdivision (10)."
    },
    {
      "id": "P5",
      "proposition": "In § 49-2-114(a), the bill replaces \"receive free or reduced-price school lunches\" with \"are members of households with an income that meet the eligibility requirements for free or reduced-price lunch as determined pursuant to 42 U.S.C. § 1758\", changing the referenced criterion from receipt of lunches to household-income eligibility.",
      "importance": "core",
      "section": "SECTION 3",
      "source_quote": "\"are members of households\n\nwith an income that meet the eligibility requirements for free or reduced-price lunch as\n\ndetermined pursuant to 42 U.S.C. § 1758\"."
    },
    {
      "id": "P6",
      "proposition": "The act takes effect July 1, 2025, and applies to the 2025-2026 school year and every school year thereafter.",
      "importance": "supporting",
      "section": "SECTION 4",
      "source_quote": "This act takes effect July 1, 2025, the public welfare requiring it, and\n\napplies to the 2025-2026 school year and each school year thereafter."
    }
  ]
}
